//! Native dimensional transport, Fourier helpers and Crank–Nicolson wrappers.
use super::Dynamic;
use super::Faces;
use super::Frame;
use super::Handle;
use super::Installer;
use super::LIMIT;
use super::NativeType;
use super::NewObject;
use super::OpError;
use super::Output;
use super::RuleError;
